CREATE DATABASE IF NOT EXISTS bella_imagen_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci; USE bella_imagen_db;
CREATE TABLE roles(id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(50) UNIQUE NOT NULL);
INSERT IGNORE INTO roles(nombre) VALUES('Administrador'),('Recepcionista'),('Especialista');
CREATE TABLE usuarios(id INT AUTO_INCREMENT PRIMARY KEY,rol_id INT NOT NULL,nombre VARCHAR(120) NOT NULL,usuario VARCHAR(60) UNIQUE NOT NULL,email VARCHAR(120) UNIQUE,password VARCHAR(255) NOT NULL,estado ENUM('Activo','Inactivo') DEFAULT 'Activo',creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(rol_id) REFERENCES roles(id));
CREATE TABLE clientes(id INT AUTO_INCREMENT PRIMARY KEY,nombres VARCHAR(100) NOT NULL,apellidos VARCHAR(100) NOT NULL,documento VARCHAR(20),telefono VARCHAR(20),email VARCHAR(120),direccion VARCHAR(200),fecha_registro TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE especialistas(id INT AUTO_INCREMENT PRIMARY KEY,nombres VARCHAR(100) NOT NULL,apellidos VARCHAR(100) NOT NULL,telefono VARCHAR(20),email VARCHAR(120),descripcion TEXT,estado ENUM('Activo','Inactivo') DEFAULT 'Activo');
ALTER TABLE usuarios ADD COLUMN especialista_id INT NULL, ADD UNIQUE KEY uq_usuario_especialista(especialista_id), ADD CONSTRAINT fk_usuario_especialista FOREIGN KEY(especialista_id) REFERENCES especialistas(id);
CREATE TABLE especialidades(id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(100) UNIQUE NOT NULL,descripcion TEXT);
CREATE TABLE especialista_especialidad(especialista_id INT NOT NULL,especialidad_id INT NOT NULL,PRIMARY KEY(especialista_id,especialidad_id),FOREIGN KEY(especialista_id) REFERENCES especialistas(id),FOREIGN KEY(especialidad_id) REFERENCES especialidades(id));
CREATE TABLE servicios(id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(120) NOT NULL,descripcion TEXT,precio DECIMAL(10,2) DEFAULT 0,duracion_minutos INT DEFAULT 30,estado ENUM('Activo','Inactivo') DEFAULT 'Activo');
CREATE TABLE especialista_servicio(especialista_id INT NOT NULL,servicio_id INT NOT NULL,PRIMARY KEY(especialista_id,servicio_id),FOREIGN KEY(especialista_id) REFERENCES especialistas(id),FOREIGN KEY(servicio_id) REFERENCES servicios(id));
CREATE TABLE productos(id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(120) NOT NULL,descripcion TEXT,stock DECIMAL(10,2) DEFAULT 0,stock_minimo DECIMAL(10,2) DEFAULT 0,unidad VARCHAR(30) DEFAULT 'Unidad',precio_compra DECIMAL(10,2) DEFAULT 0,estado ENUM('Activo','Inactivo') DEFAULT 'Activo');
CREATE TABLE citas(id INT AUTO_INCREMENT PRIMARY KEY,cliente_id INT NOT NULL,especialista_id INT NOT NULL,servicio_id INT NOT NULL,fecha DATE NOT NULL,hora_inicio TIME NOT NULL,hora_fin TIME NOT NULL,estado ENUM('Pendiente','Confirmada','En atención','Atendida','Cancelada','No asistió') DEFAULT 'Pendiente',observaciones TEXT,creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(cliente_id) REFERENCES clientes(id),FOREIGN KEY(especialista_id) REFERENCES especialistas(id),FOREIGN KEY(servicio_id) REFERENCES servicios(id),INDEX(fecha),INDEX(especialista_id,fecha));
CREATE TABLE atenciones(id INT AUTO_INCREMENT PRIMARY KEY,cita_id INT UNIQUE NOT NULL,fecha_atencion DATETIME DEFAULT CURRENT_TIMESTAMP,descripcion TEXT,observaciones TEXT,FOREIGN KEY(cita_id) REFERENCES citas(id));
CREATE TABLE atencion_productos(id INT AUTO_INCREMENT PRIMARY KEY,atencion_id INT NOT NULL,producto_id INT NOT NULL,cantidad DECIMAL(10,2) NOT NULL,FOREIGN KEY(atencion_id) REFERENCES atenciones(id),FOREIGN KEY(producto_id) REFERENCES productos(id));
CREATE TABLE tratamientos(id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(120) NOT NULL,descripcion TEXT,precio DECIMAL(10,2) DEFAULT 0,numero_sesiones INT DEFAULT 1,estado ENUM('Activo','Inactivo') DEFAULT 'Activo');
CREATE TABLE cliente_tratamientos(id INT AUTO_INCREMENT PRIMARY KEY,cliente_id INT NOT NULL,tratamiento_id INT NOT NULL,fecha_inicio DATE NOT NULL,fecha_fin DATE,sesiones_realizadas INT DEFAULT 0,estado ENUM('Activo','Finalizado','Cancelado') DEFAULT 'Activo',FOREIGN KEY(cliente_id) REFERENCES clientes(id),FOREIGN KEY(tratamiento_id) REFERENCES tratamientos(id));
CREATE TABLE pagos(id INT AUTO_INCREMENT PRIMARY KEY,cita_id INT NULL,cliente_tratamiento_id INT NULL,monto DECIMAL(10,2) NOT NULL,metodo ENUM('Efectivo','Tarjeta de crédito','Tarjeta de débito','Yape') NOT NULL,estado ENUM('Pagado','Pendiente','Anulado') DEFAULT 'Pagado',fecha_pago DATETIME DEFAULT CURRENT_TIMESTAMP,referencia VARCHAR(100),FOREIGN KEY(cita_id) REFERENCES citas(id),FOREIGN KEY(cliente_tratamiento_id) REFERENCES cliente_tratamientos(id));
CREATE TABLE horarios_especialistas(id INT AUTO_INCREMENT PRIMARY KEY,especialista_id INT NOT NULL,dia_semana TINYINT NOT NULL,hora_inicio TIME NOT NULL,hora_fin TIME NOT NULL,FOREIGN KEY(especialista_id) REFERENCES especialistas(id));
CREATE TABLE movimientos_inventario(id INT AUTO_INCREMENT PRIMARY KEY,producto_id INT NOT NULL,tipo ENUM('Entrada','Salida','Ajuste') NOT NULL,cantidad DECIMAL(10,2) NOT NULL,motivo VARCHAR(200),fecha DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(producto_id) REFERENCES productos(id));
CREATE TABLE sesiones_tratamiento(id INT AUTO_INCREMENT PRIMARY KEY,cliente_tratamiento_id INT NOT NULL,especialista_id INT NOT NULL,fecha DATETIME NOT NULL,observaciones TEXT,estado ENUM('Pendiente','Realizada','Cancelada') DEFAULT 'Pendiente',FOREIGN KEY(cliente_tratamiento_id) REFERENCES cliente_tratamientos(id),FOREIGN KEY(especialista_id) REFERENCES especialistas(id));
